ST.xhtml:p:
R_Trigger1(CLK := g_biProcessHalCloseFollow);(*关随动操作*)
F_Trigger1(CLK := g_biProcessHalCloseFollow);(*关随动操作*)

IF R_Trigger1.Q THEN
  IF Axis_Z.NCTOPLC.AxisState = 9 THEN(*随动状态下，再去关随动*)
    nCloseFollowState:=10;
  END_IF;
END_IF;

IF F_Trigger1.Q THEN
  nCloseFollowState := 0;
  g_bProcessHalCloseFollowState:= FALSE;(*引脚关随动标志位*)
END_IF;

CASE nCloseFollowState OF
  0:
    nCloseFollowState := 0;
  10:(*关随动*)
    g_bZFollowClose := TRUE;
    g_nFollowState :=180;
    IF g_bZFollowOutDone THEN
      nCloseFollowState := 0;
      g_bProcessHalCloseFollowState := TRUE;(*引脚关随动标志位*)
      g_bZFollowClose := FALSE;
    END_IF; 

END_CASE;

g_boProcessHalCloseFollowState := g_bProcessHalCloseFollowState;
